solution.solution.cpp:
class Metres
{
public:
    explicit Metres(double value) : m_value{ value } {}
    double value() const { return m_value; }

private:
    double m_value{};
};

unitTests:
static_assert(std::is_constructible_v<Metres, double>, "Metres{ 5.0 } should work");
static_assert(!std::is_convertible_v<double, Metres>, "a bare double should not turn into Metres: mark the constructor explicit");

TEST("holds its value") { const Metres m{ 5.5 }; CHECK_NEAR(m.value(), 5.5, 1e-12); }

